52: func (b Builder) Build(payloadID string, sectionPlan []Section, session runtime.SessionView, history *logs.SessionHistory, workflow *logs.WorkflowHistory) Payload {
53: 	_ = workflow
54: 	sections := append([]Section(nil), sectionPlan...)
55: 	messages := buildTranscript(history)
56: 	maxMessages := b.MaxMessages
57: 	if maxMessages <= 0 {
58: 		maxMessages = 12
59: 	}
60: 	messages = trimMessages(messages, maxMessages)
61: 	return Payload{
62: 		PayloadID: payloadID,
63: 		SessionID: sessionID(history),
64: 		AgentName: session.Agent.Name,
65: 		ModelRef:  session.Agent.ProviderRef,
66: 		Sections:  sections,
67: 		Messages:  messages,
