161: func latestUserAnchor(blocks []messageBlock) *messageBlock {
162: 	for i := len(blocks) - 1; i >= 0; i-- {
163: 		if blocks[i].Anchor {
164: 			anchor := blocks[i]
165: 			return &anchor
166: 		}
167: 	}
168: 	return nil
169: }
