86: func workflowProgress(workflow *runtime.WorkflowView, history *logs.SessionHistory) ([]string, []string, bool) {
87: 	required := []string{"repo_orientation", "clarification"}
88: 	visited := map[string]bool{}
89: 	if workflow.CurrentState != "" {
90: 		visited[workflow.CurrentState] = true
91: 	}
92: 	if history != nil {
93: 		for _, record := range history.Records {
94: 			transition, ok := record.(logs.WorkflowTransitionRefRecord)
95: 			if ok {
96: 				visited[transition.ToState] = true
97: 				continue
98: 			}
99: 			transitionPtr, ok := record.(*logs.WorkflowTransitionRefRecord)
100: 			if ok {
101: 				visited[transitionPtr.ToState] = true
102: 			}
103: 		}
104: 	}
105: 	completed := []string{}
106: 	for _, state := range []string{"intake", "repo_orientation", "clarification", "planning", "plan_review", "implementation", "validation"} {
107: 		if visited[state] {
108: 			completed = append(completed, state)
109: 		}
